    let idx00 = base + u32(c0.y) * tu + u32(c0.x);
    let idx10 = base + u32(c0.y) * tu + u32(c1.x);
    let idx01 = base + u32(c1.y) * tu + u32(c0.x);
    let idx11 = base + u32(c1.y) * tu + u32(c1.x);

